fn cooking_with_missing_appliances_matches_the_reference() {
    for &(input, index) in CASES {
        let line = crate::bot::understanding::line::normalise(input);
        assert_eq!(super::without(&line).as_deref(), OUTCOMES[index], "{input}");
    }
}
